package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Activates per-user local accounts while preserving the existing MFIX feature chain. */
public class UserAccountsActivePatchActivity extends BusinessSettingsPatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixUserAccountsActive)return;window.__mfixUserAccountsActive=true;"+
        "var KEY='mfix_users_v2';"+
        "function esc(s){return String(s==null?'':s).replace(/[&<>\\\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\\\"':'&quot;',\"'\":'&#39;'}[c];});}"+
        "function read(){try{var a=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(a)?a:[]}catch(e){return []}}"+
        "function write(a){localStorage.setItem(KEY,JSON.stringify(a));}"+
        "function roleLabel(r){return r==='manager'?'מנהל':'קופאי';}"+
        "function card(){var v=document.getElementById('view-settings');if(!v)return false;if(document.getElementById('mfixUserAccountsCard'))return true;var b=document.createElement('div');b.id='mfixUserAccountsCard';b.className='card';b.style.marginBottom='12px';b.innerHTML='<div class=\"section-title\">👥 משתמשים והרשאות</div><div class=\"muted\" style=\"font-size:12px;margin-bottom:10px\">לכל משתמש שם, תפקיד ו-PIN נפרדים. קופאי אינו מקבל גישה להגדרות ולדוחות כאשר הרשאות תפקידים פעילות.</div><div id=\"mfixUserAccountsList\"></div><button class=\"btn btn-primary\" type=\"button\" id=\"mfixUserAdd\">➕ הוסף משתמש</button>';v.insertBefore(b,v.firstChild);function draw(){var a=read(),w=b.querySelector('#mfixUserAccountsList');w.innerHTML=a.length?'<table class=\"tbl\"><thead><tr><th>משתמש</th><th>תפקיד</th><th>מצב</th><th>פעולות</th></tr></thead><tbody>'+a.map(function(u,i){return '<tr><td><b>'+esc(u.name)+'</b></td><td><span class=\"pill '+(u.role==='manager'?'blue':'gray')+'\">'+roleLabel(u.role)+'</span></td><td><span class=\"pill '+(u.active===false?'red':'green')+'\">'+(u.active===false?'מושבת':'פעיל')+'</span></td><td><button class=\"btn btn-ghost\" data-edit=\"'+i+'\">✏️</button> <button class=\"btn btn-ghost\" data-toggle=\"'+i+'\">'+(u.active===false?'הפעל':'השבת')+'</button> <button class=\"btn btn-ghost\" style=\"color:var(--red-600)\" data-del=\"'+i+'\">🗑️</button></td></tr>';}).join('')+'</tbody></table>':'<div class=\"empty-state\" style=\"padding:18px\">אין משתמשים נוספים. המשתמשים הוותיקים של מנהל/קופאי עדיין נתמכים.</div>';w.querySelectorAll('[data-edit]').forEach(function(x){x.onclick=function(){edit(Number(x.dataset.edit));};});w.querySelectorAll('[data-toggle]').forEach(function(x){x.onclick=function(){var a=read(),i=Number(x.dataset.toggle);if(a[i])a[i].active=a[i].active===false;write(a);draw();};});w.querySelectorAll('[data-del]').forEach(function(x){x.onclick=function(){var a=read(),i=Number(x.dataset.del);if(a[i]&&!confirm('למחוק את המשתמש '+a[i].name+'?'))return;a.splice(i,1);write(a);draw();};});}function edit(i){var a=read(),u=i>=0?a[i]:{name:'',role:'cashier',pin:'',active:true};openModal('<div class=\"modal-head\"><h3>'+(i>=0?'עריכת משתמש':'משתמש חדש')+'</h3><button class=\"modal-close\" onclick=\"closeModal()\">✕</button></div><div class=\"modal-body\"><div class=\"field\"><label class=\"flabel\">שם משתמש</label><input class=\"input\" id=\"mua_name\" maxlength=\"40\" value=\"'+esc(u.name||'')+'\"></div><div class=\"grid2\"><div class=\"field\"><label class=\"flabel\">תפקיד</label><select class=\"input\" id=\"mua_role\"><option value=\"cashier\" '+(u.role==='cashier'?'selected':'')+'>קופאי</option><option value=\"manager\" '+(u.role==='manager'?'selected':'')+'>מנהל</option></select></div><div class=\"field\"><label class=\"flabel\">PIN (4–12 ספרות)</label><input class=\"input\" id=\"mua_pin\" type=\"password\" inputmode=\"numeric\" maxlength=\"12\" value=\"'+esc(u.pin||'')+'\"></div></div><div id=\"mua_err\" style=\"color:var(--red-600);font-size:12px\"></div></div><div class=\"modal-foot\"><button class=\"btn btn-ghost\" onclick=\"closeModal()\">ביטול</button><button class=\"btn btn-primary\" id=\"mua_save\">שמור</button></div>');document.getElementById('mua_save').onclick=function(){var name=document.getElementById('mua_name').value.trim(),role=document.getElementById('mua_role').value,pin=document.getElementById('mua_pin').value.trim(),e=document.getElementById('mua_err');if(!name){e.textContent='יש להזין שם משתמש';return;}if(!/^\\d{4,12}$/.test(pin)){e.textContent='PIN חייב להכיל 4–12 ספרות';return;}if(a.some(function(x,j){return j!==i&&String(x.name).toLowerCase()===name.toLowerCase();})){e.textContent='שם המשתמש כבר קיים';return;}var n={id:i>=0&&a[i]?a[i].id:'u_'+Date.now().toString(36),name:name,role:role,pin:pin,active:i>=0&&a[i]?a[i].active!==false:true};if(i>=0)a[i]=n;else a.push(n);write(a);closeModal();draw();toast('המשתמש נשמר','ok');};}b.querySelector('#mfixUserAdd').onclick=function(){edit(-1);};draw();return true;}"+
        "function patchLogin(){if(typeof window.openRoleLoginModal!=='function'||window.__mfixUserLoginWrapped)return;var oldOpen=window.openRoleLoginModal,oldAttempt=window.attemptRoleLogin;window.openRoleLoginModal=function(m){oldOpen(m);setTimeout(function(){var body=document.querySelector('#modalOverlay .modal-body');if(!body||document.getElementById('mua_loginUser'))return;var f=document.createElement('div');f.className='field';f.innerHTML='<label class=\"flabel\">שם משתמש (אופציונלי)</label><input class=\"input\" id=\"mua_loginUser\" autocomplete=\"username\" placeholder=\"לדוגמה: קופאי1\">';body.insertBefore(f,body.firstChild);},40);};window.attemptRoleLogin=function(role){var name=(document.getElementById('mua_loginUser')?.value||'').trim().toLowerCase(),pin=(document.getElementById('loginPin')?.value||'').trim();if(!name){return oldAttempt(role);}var a=read(),u=a.find(function(x){return x.active!==false&&String(x.name||'').toLowerCase()===name;});var e=document.getElementById('loginError');if(!u){if(e)e.textContent='משתמש לא נמצא או מושבת';return;}if(u.role!==role){if(e)e.textContent='התפקיד שנבחר אינו תואם למשתמש';return;}if(pin!==u.pin){if(e)e.textContent='קוד PIN שגוי';return;}STATE.currentRole=u.role;STATE.currentUserId=u.id;STATE.currentUserName=u.name;if(!tabAllowed(STATE.activeTab))STATE.activeTab='pos';if(typeof logAction==='function')logAction('כניסת משתמש',u.name+' ('+roleLabel(u.role)+')');if(typeof persist==='function')persist('auditLog');closeModal();forceShellRebuild();toast('מחוברים כ'+u.name+' — '+roleLabel(u.role),'ok');};window.__mfixUserLoginWrapped=true;}"+
        "var n=0;function loop(){n++;card();patchLogin();if(n<100)setTimeout(loop,700);}loop();console.log('[MFIX] user accounts active');})();";

    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView)((WebView)root).postDelayed(()->((WebView)root).evaluateJavascript(PATCH,null),10500);
    }
}
